12	import { LEAD_SOURCES, LEAD_STATUSES } from "./types";
13	
14	// In-memory stand-in for the agency's Postgres. Latencies mirror what the
15	// production database reports for the same queries on a busy workspace.
16	
17	type Store = {
18	  workspaces: Workspace[];
19	  users: User[];
20	  leads: Lead[];
21	  audit: AuditEntry[];
