134	
135	const UTM_BY_SOURCE: Record<LeadSource, [string | null, string | null]> = {
136	  website: [null, null],
137	  "google-ads": ["google", "cpc"],
138	  "facebook-ads": ["facebook", "paid_social"],
139	  linkedin: ["linkedin", "paid_social"],
140	  referral: ["partner", "referral"],
141	  webinar: ["webinar", "email"],
142	};
143	
144	const CAMPAIGNS = ["autumn-2026", "dental-q3", "brand-search", "retargeting", "webinar-sept"];
145	
146	// Reference "now" for the seed so dates do not drift between runs.
147	const SEED_NOW = Date.parse("2026-09-20T12:00:00.000Z");
148	const DAY_MS = 24 * 60 * 60 * 1000;
149	
150	function slugify(value: string) {
151	  return value
152	    .toLowerCase()
153	    .replace(/&/g, "and")
154	    .normalize("NFD")
155	    .replace(/[̀-ͯ]/g, "")
156	    .replace(/[^a-z0-9]+/g, "-")
157	    .replace(/(^-|-$)/g, "");
158	}
159	
160	function leadId(n: number) {
161	  return `lead_${String(n).padStart(4, "0")}`;
162	}
163	
164	function seedLeads(count: number, workspaces: Workspace[], users: User[]): Lead[] {
165	  const random = mulberry32(20260921);
166	  const pick = <T,>(items: readonly T[]) => items[Math.floor(random() * items.length)];
167	  const leads: Lead[] = [];
168	
169	  for (let n = 1; n <= count; n++) {
170	    const workspace = n % 7 === 0 ? workspaces[1] : workspaces[0];
171	    const managers = users.filter((u) => u.workspaceSlug === workspace.slug);
172	    const firstName = pick(FIRST_NAMES);
173	    const lastName = pick(LAST_NAMES);
174	    const company = pick(COMPANIES);
175	    const [city, country] = pick(CITIES);
176	    const source = pick(LEAD_SOURCES);
177	    const [utmSource, utmMedium] = UTM_BY_SOURCE[source];
178	    const utmCampaign = utmSource ? pick(CAMPAIGNS) : null;
179	    const statusRoll = random();
180	    const status: LeadStatus =
181	      statusRoll < 0.35 ? "new"
182	      : statusRoll < 0.6 ? "contacted"
183	      : statusRoll < 0.78 ? "qualified"
184	      : statusRoll < 0.9 ? "won"
185	      : "lost";
186	    const createdAt = new Date(SEED_NOW - Math.floor(random() * 90 * DAY_MS));
187	    const updatedAt = new Date(createdAt.getTime() + Math.floor(random() * 5 * DAY_MS));
188	    const email = `${slugify(firstName)}.${slugify(lastName)}${n}@example.test`;
189	    const phone = `+380 00 ${String(100 + Math.floor(random() * 900))} ${String(10 + Math.floor(random() * 90))} ${String(10 + Math.floor(random() * 90))}`;
190	    const ipAddress = `${pick(TEST_NETS)}.${1 + Math.floor(random() * 254)}`;
191	    const userAgent = pick(USER_AGENTS);
192	    const budget = pick(BUDGETS);
193	    const message = pick(MESSAGES);
194	    const website = `https://${slugify(company)}.example.test`;
195	    const consentMarketing = random() < 0.6;
196	
197	    leads.push({
198	      id: leadId(n),
199	      workspaceId: workspace.id,
200	      firstName,
201	      lastName,
202	      fullName: `${firstName} ${lastName}`,
203	      email,
204	      phone,
205	      company,
206	      jobTitle: pick(JOB_TITLES),
207	      website,
208	      city,
209	      country,
210	      source,
211	      utmSource,
212	      utmMedium,
213	      utmCampaign,
214	      budget,
215	      message,
216	      status,
217	      score: Math.floor(random() * 101),
218	      assignedTo: status === "new" ? null : pick(managers).name,
219	      tags: TAGS.filter(() => random() < 0.2),
220	      consentMarketing,
221	      ipAddress,
222	      userAgent,
223	      rawPayload: {
224	        form: {
225	          id: "contact-main",
226	          version: "2026-07",
227	          fields: { firstName, lastName, email, phone, company, website, budget, message, consentMarketing },
228	        },
229	        tracking: {
230	          utm_source: utmSource,
231	          utm_medium: utmMedium,
232	          utm_campaign: utmCampaign,
233	          gclid: source === "google-ads" ? `Cj0KCQjw${Math.floor(random() * 1e9).toString(36)}` : null,
234	          fbclid: source === "facebook-ads" ? `IwAR${Math.floor(random() * 1e9).toString(36)}` : null,
