python3 - <<'EOF'
import re
p='lib/db.ts'
s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''  NewLead,
  SourceCount,''','''  NewLead,
  NewQuote,
  Quote,
  QuoteResult,
  SourceCount,''')
rep('''  audit: AuditEntry[];
  nextLeadNumber: number;''','''  audit: AuditEntry[];
  quotes: Quote[];
  nextLeadNumber: number;''')
rep('''  createSession: 50,
} as const;''','''  createSession: 50,
  insertQuote: 120,
  getQuote: 80,
  completeQuote: 80,
} as const;''')
rep('''  return { workspaces, users, leads, audit: [], nextLeadNumber: leads.length + 1 };''','''  return { workspaces, users, leads, audit: [], quotes: [], nextLeadNumber: leads.length + 1 };''')
rep('''const store = (globalForStore.leadDeskStore ??= createStore());''','''const store = (globalForStore.leadDeskStore ??= createStore());
// A store created by an older version of this module during `next dev` has no quotes yet.
store.quotes ??= [];''')
rep('''  insertAuditEntry(entry: AuditEntry) {''','''  insertQuote(input: NewQuote) {
    return query("insertQuote", (): Quote => {
      const now = new Date().toISOString();
      const quote: Quote = {
        ...input,
        // Random, not sequential: the id is the only key to the public /quotes/[id] page.
        id: `quote_${crypto.randomUUID()}`,
        status: "pending",
        pdfUrl: null,
        error: null,
        createdAt: now,
        updatedAt: now,
      };
      store.quotes.push(quote);
      return structuredClone(quote);
    });
  },

  getQuote(id: string) {
    return query("getQuote", () => {
      const quote = store.quotes.find((q) => q.id === id);
      return quote ? structuredClone(quote) : null;
    });
  },

  // Only a pending quote can be completed: a late or repeated callback cannot overwrite the result.
  completeQuote(id: string, result: QuoteResult) {
    return query("completeQuote", () => {
      const quote = store.quotes.find((q) => q.id === id);
      if (!quote || quote.status !== "pending") return false;
      quote.status = result.status;
      quote.pdfUrl = result.status === "ready" ? result.pdfUrl : null;
      quote.error = result.status === "failed" ? result.error : null;
      quote.updatedAt = new Date().toISOString();
      return true;
    });
  },

  insertAuditEntry(entry: AuditEntry) {''')
open(p,'w').write(s)
EOF
